update public.products set description='Fresh chicken liver is poultry offal with a soft texture and rich savoury flavour, suitable for frying, stews, sauces and other thoroughly cooked dishes.', handling_protocols=array['Keep raw liver cold and separated from ready-to-eat foods.','Handle with clean utensils and thoroughly clean hands and surfaces afterwards.','Cook thoroughly to at least 74°C / 165°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Chicken Liver' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='A mixed selection of chicken portions intended for soups, stews, rice dishes and other meals that use a combination of poultry cuts.', handling_protocols=array['Treat the entire pack as raw poultry and keep it cold and separated from ready-to-eat foods.','Do not wash raw chicken; clean hands, utensils and preparation surfaces after handling.','Cook every component thoroughly to at least 74°C / 165°F.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','Because the pack composition is not yet defined, use the conservative frozen quality target of about 3–4 months at -18°C or below.']::text[] where name='Chicken Assorted' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
